<?php
declare(strict_types=1);
namespace EasyIT\LicenseServer\Customer;
use EasyIT\LicenseServer\Database\Connection;
use EasyIT\LicenseServer\Database\MigrationRunner;
use EasyIT\LicenseServer\Service\AuditService;
use EasyIT\LicenseServer\Service\CustomerCredentialService;
use EasyIT\LicenseServer\Service\LicenseService;
use EasyIT\LicenseServer\Service\SurfacePolicyService;
use EasyIT\LicenseServer\Support\Id;
use PDO;
final class CustomerPortalApp{
 private PDO $pdo;private CustomerAuth $auth;private AuditService $audit;private LicenseService $licenses;private SurfacePolicyService $surface;private string $base;
 public static function run(array $cfg):never{$a=new self($cfg);$a->dispatch();exit;}
 private function __construct(private array $cfg){$this->pdo=Connection::create($cfg['database']);(new MigrationRunner($this->pdo))->migrate();$this->audit=new AuditService($this->pdo);$this->licenses=new LicenseService($this->pdo);$this->surface=new SurfacePolicyService($this->pdo,$cfg['network']??[]);$this->auth=new CustomerAuth($this->pdo,$this->audit,$cfg);$this->auth->startSession();$script=str_replace('\\','/',(string)($_SERVER['SCRIPT_NAME']??'/customer/index.php'));$this->base=rtrim(dirname($script),'/');$this->securityHeaders();}
 private function dispatch():never{$page=(string)($_GET['page']??'dashboard');$m=strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET'));try{if($page==='login'){if($m==='POST')$this->postLogin();$this->renderLogin();}if($page==='logout'){if($m==='POST'){$this->auth->verifyCsrf((string)($_POST['csrf']??''));$this->auth->logout();}$this->redirect('login');}$u=$this->auth->user();if(!$u)$this->redirect('login');if($m==='POST'){$this->auth->verifyCsrf((string)($_POST['csrf']??''));$this->handlePost($page,$u);}match($page){'dashboard'=>$this->dashboard($u),'profile'=>$this->profile($u),'surface'=>$this->surfacePage($u),'licenses'=>$this->licensesPage($u),'password'=>$this->passwordPage($u),default=>$this->dashboard($u)};}catch(\Throwable $e){$this->auth->flash('error',$this->publicError($e->getMessage()));if($m==='POST')$this->redirect((string)($_POST['return_page']??'dashboard'));$u=$this->auth->user();if(!$u)$this->renderLogin();$this->dashboard($u);}}
 private function handlePost(string $p,array $u):void{$a=(string)($_POST['action']??'');if($p==='profile'&&$a==='save_profile')$this->saveProfile($u);if($p==='surface'&&$a==='add_domain')$this->addDomain($u);if($p==='surface'&&$a==='remove_domain')$this->removeDomain($u);if($p==='surface'&&$a==='add_network')$this->addNetwork($u);if($p==='surface'&&$a==='remove_network')$this->removeNetwork($u);if($p==='password'&&$a==='change_password')$this->changePassword($u);throw new \RuntimeException('CUSTOMER_ACTION_INVALID');}
 private function postLogin():never{$this->auth->verifyCsrf((string)($_POST['csrf']??''));if(!$this->auth->login((string)($_POST['username']??''),(string)($_POST['password']??''))){$this->auth->flash('error','Anmeldung fehlgeschlagen.');$this->redirect('login');}$this->redirect('dashboard');}
 private function customer(array $u):array{$st=$this->pdo->prepare('SELECT * FROM customers WHERE customer_id=? LIMIT 1');$st->execute([$u['customer_id']]);$r=$st->fetch();if(!$r)throw new \RuntimeException('CUSTOMER_NOT_FOUND');return$r;}
 private function saveProfile(array $u):never{$fields=['legal_name','contact_name','phone','mobile','website','street','postal_code','city','state_region','country_code','vat_id','billing_email','technical_email'];$v=[];foreach($fields as $f)$v[$f]=trim((string)($_POST[$f]??''));foreach(['billing_email','technical_email'] as $f)if($v[$f]!==''&&!filter_var($v[$f],FILTER_VALIDATE_EMAIL))throw new \RuntimeException('EMAIL_INVALID');$sql='UPDATE customers SET '.implode(',',array_map(fn($f)=>$f.'=?',$fields)).',updated_at=? WHERE customer_id=?';$args=array_map(fn($f)=>$v[$f]!==''?$v[$f]:null,$fields);$args[]=time();$args[]=$u['customer_id'];$this->pdo->prepare($sql)->execute($args);$this->audit->write('CUSTOMER_SELF_PROFILE_UPDATED','customer',$u['customer_id'],'customer_user',$u['id']);$this->auth->flash('success','Stammdaten wurden gespeichert.');$this->redirect('profile');}
 private function assertSurface(array $u):void{$c=$this->customer($u);if((int)($c['surface_self_service']??0)!==1)throw new \RuntimeException('CUSTOMER_SURFACE_SELF_SERVICE_DISABLED');}
 private function addDomain(array $u):never{$this->assertSurface($u);$d=$this->surface->normalizeDomainPattern((string)($_POST['domain']??''));$n=time();try{$this->pdo->prepare('INSERT INTO customer_allowed_domains (rule_id,customer_id,domain_pattern,status,created_at,updated_at) VALUES (?,?,?,?,?,?)')->execute([Id::make('DOM'),$u['customer_id'],$d,'active',$n,$n]);}catch(\Throwable){$this->pdo->prepare("UPDATE customer_allowed_domains SET status='active',updated_at=? WHERE customer_id=? AND domain_pattern=?")->execute([$n,$u['customer_id'],$d]);}$this->audit->write('CUSTOMER_DOMAIN_ADDED','customer',$u['customer_id'],'customer_user',$u['id'],null,[],['domain'=>$d]);$this->redirect('surface');}
 private function removeDomain(array $u):never{$this->assertSurface($u);$this->surface->removeDomainRuleSafely((string)$u['customer_id'],(string)($_POST['rule_id']??''));$this->redirect('surface');}
 private function addNetwork(array $u):never{$this->assertSurface($u);$d=$this->surface->normalizeCidr((string)($_POST['cidr']??''));$n=time();try{$this->pdo->prepare('INSERT INTO customer_allowed_networks (rule_id,customer_id,cidr,status,created_at,updated_at) VALUES (?,?,?,?,?,?)')->execute([Id::make('NET'),$u['customer_id'],$d,'active',$n,$n]);}catch(\Throwable){$this->pdo->prepare("UPDATE customer_allowed_networks SET status='active',updated_at=? WHERE customer_id=? AND cidr=?")->execute([$n,$u['customer_id'],$d]);}$this->audit->write('CUSTOMER_NETWORK_ADDED','customer',$u['customer_id'],'customer_user',$u['id'],null,[],['cidr'=>$d]);$this->redirect('surface');}
 private function removeNetwork(array $u):never{$this->assertSurface($u);$this->surface->removeNetworkRuleSafely((string)$u['customer_id'],(string)($_POST['rule_id']??''));$this->redirect('surface');}
 private function changePassword(array $u):never{$svc=new CustomerCredentialService($this->pdo,$this->audit);$version=$svc->changePassword((string)$u['customer_id'],(string)$u['id'],(string)($_POST['old_password']??''),(string)($_POST['new_password']??''),(string)($_POST['new_password_confirm']??''),(string)$u['id']);$this->auth->acceptCredentialVersion($version);$this->auth->flash('success','Kennwort wurde geändert. Andere aktive Anmeldungen wurden beendet.');$this->redirect('password');}
 private function renderLogin():never{$this->publicPage('Kundenportal','<div class="auth-card"><h1>easyIT Kundenportal</h1>'.$this->alerts().'<form method="post"><input type="hidden" name="csrf" value="'.self::h($this->auth->csrf()).'"><label>Benutzername<input name="username" required autofocus></label><label>Kennwort<input type="password" name="password" required></label><button class="primary">Anmelden</button></form></div>');}
 private function dashboard(array $u):never{$c=$this->customer($u);$q=$this->pdo->prepare('SELECT COUNT(*) c FROM licenses WHERE customer_id=?');$q->execute([$u['customer_id']]);$lc=(int)($q->fetch()['c']??0);$q=$this->pdo->prepare("SELECT COUNT(*) c FROM license_dataform_usage d JOIN licenses l ON l.license_id=d.license_id WHERE l.customer_id=? AND d.status='active'");$q->execute([$u['customer_id']]);$dc=(int)($q->fetch()['c']??0);$b='<h1>Dashboard</h1>'.$this->alerts().'<p>'.self::h(($c['customer_key']??$c['customer_number']).' · '.($c['legal_name']?:$c['company']?:$c['name'])).'</p><div class="cards">'.$this->card('Lizenzen',$lc).$this->card('freigegebene DataForms',$dc).'</div><section><h2>Herkunftsregeln</h2><p>Domainprüfung: <strong>'.((int)$c['surface_domain_required']===1?'aktiv':'inaktiv').'</strong><br>IP-Prüfung: <strong>'.((int)$c['surface_ip_required']===1?'aktiv':'inaktiv').'</strong></p></section>';$this->portalPage('Dashboard',$b,$u);}
 private function profile(array $u):never{$c=$this->customer($u);$f=fn($n,$l,$t='text')=>'<label>'.$l.'<input type="'.$t.'" name="'.$n.'" value="'.self::h($c[$n]??'').'"></label>';$b='<h1>Meine Stammdaten</h1>'.$this->alerts().'<section><form method="post"><input type="hidden" name="csrf" value="'.self::h($this->auth->csrf()).'"><input type="hidden" name="action" value="save_profile"><div class="grid2">'.$f('legal_name','Rechtlicher Firmenname').$f('contact_name','Ansprechpartner').'<label>Kunden-E-Mail / Kundenschlüssel<input type="email" value="'.self::h($c['customer_key']??$c['email']??'').'" readonly></label>'.$f('phone','Telefon').$f('mobile','Mobil').$f('website','Website').$f('street','Straße/Hausnummer').$f('postal_code','PLZ').$f('city','Ort').$f('state_region','Bundesland/Region').$f('country_code','Land (ISO)').$f('vat_id','USt-ID').$f('billing_email','Rechnungs-E-Mail','email').$f('technical_email','Technische E-Mail','email').'</div><button class="primary">Speichern</button></form></section>';$this->portalPage('Stammdaten',$b,$u);}
 private function surfacePage(array $u):never{$c=$this->customer($u);$q=$this->pdo->prepare("SELECT * FROM customer_allowed_domains WHERE customer_id=? AND status='active' ORDER BY domain_pattern");$q->execute([$u['customer_id']]);$ds=$q->fetchAll();$q=$this->pdo->prepare("SELECT * FROM customer_allowed_networks WHERE customer_id=? AND status='active' ORDER BY cidr");$q->execute([$u['customer_id']]);$ns=$q->fetchAll();$e=(int)($c['surface_self_service']??0)===1;$b='<h1>Domains / IP-Freigaben</h1>'.$this->alerts().'<section><p>Nur freigegebene Herkunftsbereiche dürfen DataForm-Runtimes starten. '.($e?'Sie dürfen diese Regeln selbst pflegen.':'Änderungen sind durch den Lizenzadministrator gesperrt.').'</p></section><div class="grid2"><section><h2>Domains</h2>';if($e)$b.=$this->addForm('add_domain','domain','example.de oder *.example.de');$b.=$this->rules($ds,'domain_pattern','remove_domain',$e).'</section><section><h2>IP/Netze</h2>';if($e)$b.=$this->addForm('add_network','cidr','203.0.113.10 oder 203.0.113.0/24');$b.=$this->rules($ns,'cidr','remove_network',$e).'</section></div>';$this->portalPage('Domains / IP',$b,$u);}
 private function licensesPage(array $u):never{$q=$this->pdo->prepare('SELECT * FROM licenses WHERE customer_id=? ORDER BY created_at DESC');$q->execute([$u['customer_id']]);$b='<h1>Meine Lizenzen</h1>'.$this->alerts();foreach($q->fetchAll() as $l){$p=$this->licenses->policySummary((string)$l['license_id']);$d=$this->pdo->prepare('SELECT project_id,dataform_id,status,last_used_at FROM license_dataform_usage WHERE license_id=? ORDER BY project_id,dataform_id');$d->execute([$l['license_id']]);$b.='<section><h2>'.self::h($l['license_number']).'</h2><p>Status: '.self::h($l['status']).' · DataForms: '.(int)$p['used_dataforms'].' / '.($p['max_dataforms']===null?'∞':(int)$p['max_dataforms']).'</p><table><thead><tr><th>Projekt</th><th>DataForm</th><th>Status</th></tr></thead><tbody>';foreach($d->fetchAll() as $r)$b.='<tr><td>'.self::h($r['project_id']).'</td><td>'.self::h($r['dataform_id']).'</td><td>'.self::h($r['status']).'</td></tr>';$b.='</tbody></table></section>';}$this->portalPage('Lizenzen',$b,$u);}
 private function passwordPage(array $u):never{$b='<h1>Kennwort ändern</h1>'.$this->alerts().'<section><form method="post"><input type="hidden" name="csrf" value="'.self::h($this->auth->csrf()).'"><input type="hidden" name="action" value="change_password"><label>Aktuelles Kennwort<input type="password" name="old_password" required></label><label>Neues Kennwort<input type="password" name="new_password" required></label><label>Wiederholen<input type="password" name="new_password_confirm" required></label><button class="primary">Speichern</button></form></section>';$this->portalPage('Kennwort',$b,$u);}
 private function addForm(string $a,string $n,string $ph):string{return'<form method="post" class="inlineform"><input type="hidden" name="csrf" value="'.self::h($this->auth->csrf()).'"><input type="hidden" name="action" value="'.$a.'"><input name="'.$n.'" placeholder="'.self::h($ph).'" required><button class="primary">Hinzufügen</button></form>';}
 private function rules(array $rows,string $col,string $action,bool $e):string{$h='<table><tbody>';foreach($rows as $r){$h.='<tr><td>'.self::h($r[$col]).'</td><td>';if($e)$h.='<form method="post"><input type="hidden" name="csrf" value="'.self::h($this->auth->csrf()).'"><input type="hidden" name="action" value="'.$action.'"><input type="hidden" name="rule_id" value="'.self::h($r['rule_id']).'"><button>Entfernen</button></form>';$h.='</td></tr>';}$h.='</tbody></table>';return$h;}
 private function portalPage(string $t,string $b,array $u):never{echo'<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::h($t).'</title>'.$this->style().'<header><div class="brand">easyIT <span>Kundenportal</span></div><div>'.self::h($u['display_name']).' <form class="inline" method="post" action="?page=logout"><input type="hidden" name="csrf" value="'.self::h($this->auth->csrf()).'"><button class="linkbtn">Abmelden</button></form></div></header><div class="shell"><nav>'.$this->nav($t).'</nav><main>'.$b.'</main></div>';exit;}
 private function publicPage(string $t,string $b):never{echo'<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::h($t).'</title>'.$this->style().'<body class="auth"><main>'.$b.'</main>';exit;}
 private function nav(string $t):string{$m=['Dashboard'=>'dashboard','Stammdaten'=>'profile','Domains / IP'=>'surface','Lizenzen'=>'licenses','Kennwort'=>'password'];$h='';foreach($m as $l=>$p)$h.='<a'.($l===$t?' class="active"':'').' href="?page='.$p.'">'.self::h($l).'</a>';return$h;}
 private function redirect(string $p):never{header('Location: '.$this->base.'/?page='.rawurlencode($p),true,303);exit;}
 private function alerts():string{$h='';foreach($this->auth->consumeFlash() as $f)$h.='<div class="alert '.self::h($f['type']).'">'.self::h($f['message']).'</div>';return$h;}
 private function publicError(string $c):string{return match($c){'EMAIL_INVALID'=>'E-Mail-Adresse ist ungültig.','CUSTOMER_SURFACE_SELF_SERVICE_DISABLED'=>'Diese Einstellungen dürfen nur vom Lizenzadministrator geändert werden.','SURFACE_DOMAIN_INVALID'=>'Domain ungültig.','SURFACE_IP_INVALID'=>'IP-/Netzangabe ungültig.','SURFACE_DOMAIN_LAST_REQUIRED'=>'Die letzte aktive Domainfreigabe kann bei verpflichtender Domainprüfung nicht entfernt werden.','SURFACE_IP_LAST_REQUIRED'=>'Die letzte aktive IP-/Netzfreigabe kann bei verpflichtender IP-Prüfung nicht entfernt werden.','SURFACE_DOMAIN_CURRENT_REQUIRED'=>'Diese Domain wird für den aktuellen Zugriff benötigt.','SURFACE_IP_CURRENT_REQUIRED'=>'Diese IP-/Netzfreigabe wird für den aktuellen Zugriff benötigt.','PASSWORD_MISMATCH'=>'Kennwörter stimmen nicht überein.','PASSWORD_WEAK'=>'Kennwort zu schwach.','PASSWORD_CURRENT_INVALID'=>'Aktuelles Kennwort ist falsch.','ACCOUNT_PASSWORD_MISMATCH'=>'Kennwörter stimmen nicht überein.','ACCOUNT_PASSWORD_WEAK'=>'Kennwort zu schwach.','ACCOUNT_PASSWORD_CURRENT_INVALID'=>'Aktuelles Kennwort ist falsch.','ACCOUNT_PASSWORD_UNCHANGED'=>'Das neue Kennwort muss sich vom bisherigen Kennwort unterscheiden.','CUSTOMER_CSRF_INVALID'=>'Sitzung abgelaufen.',default=>'Die Aktion konnte nicht ausgeführt werden.'};}
 private function card(string $t,mixed $v):string{return'<div class="card"><span>'.self::h($t).'</span><strong>'.self::h($v).'</strong></div>';}
 private function securityHeaders():void{header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('Referrer-Policy: no-referrer');header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; img-src 'self' data:; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");header('Cache-Control: no-store, max-age=0');}
 private static function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
 private function style():string{return <<<'HTML'
<style>:root{font-family:Arial,sans-serif;color:#20242a;background:#f5f6f8}*{box-sizing:border-box}body{margin:0;background:#f5f6f8}header{height:58px;background:#17202a;color:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 24px}.brand{font-size:20px;font-weight:700}.brand span{font-weight:400;color:#cbd5df}.shell{display:grid;grid-template-columns:210px 1fr;min-height:calc(100vh - 58px)}nav{background:#fff;border-right:1px solid #dfe3e8;padding:20px 10px}nav a{display:block;padding:10px 12px;margin:2px 0;border-radius:6px;color:#28323c;text-decoration:none}nav a.active,nav a:hover{background:#e9eef4;font-weight:700}main{padding:26px;max-width:1300px;width:100%}section{background:#fff;border:1px solid #dfe3e8;border-radius:8px;padding:20px;margin:18px 0;overflow:auto}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.card{background:#fff;border:1px solid #dfe3e8;border-radius:8px;padding:18px}.card span{display:block;color:#6a737d}.card strong{font-size:26px}.grid2{display:grid;grid-template-columns:repeat(2,minmax(220px,1fr));gap:14px}label{display:block;font-weight:600;font-size:14px;margin-bottom:12px}input{width:100%;padding:9px 10px;border:1px solid #b9c0c8;border-radius:5px;margin-top:5px;font:inherit}button{border:1px solid #9aa4ad;border-radius:5px;padding:8px 12px;background:#fff;cursor:pointer}.primary{background:#1f5f99;color:#fff;border-color:#1f5f99}.linkbtn{background:transparent;border:0;color:#fff}.inline{display:inline}.inlineform{display:grid;grid-template-columns:1fr auto;gap:8px}.alert{border-radius:6px;padding:11px 13px;margin:10px 0}.alert.success{background:#eaf7ee;color:#145a2d;border:1px solid #a7dbb8}.alert.error{background:#fff0f0;color:#8a1c1c;border:1px solid #e5b1b1}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px 8px;border-bottom:1px solid #e2e5e8}.auth{display:flex;min-height:100vh;justify-content:center;padding-top:9vh}.auth main{max-width:520px}.auth-card{background:#fff;border:1px solid #dfe3e8;border-radius:10px;padding:28px;box-shadow:0 8px 28px rgba(0,0,0,.08)}@media(max-width:850px){.shell{grid-template-columns:1fr}.grid2{grid-template-columns:1fr}nav{border-right:0;border-bottom:1px solid #dfe3e8}}</style>
HTML;}
}
